javascript:void(function(){ if(window.__MINES_BOT){window.__MINES_BOT.toggle();return} var C={ baseBet:3.1799, mines:4, picks:2, multiOnLoss:3, maxLossStreak:3, maxRounds:500, delayRound:2500, delayClick:800, delayAfterBet:1500 }; var S={betInput:'',betButton:'',cashoutButton:'',tiles:'',balance:''}; var ST={ running:false,stop:false, bet:C.baseBet,lossStreak:0, rounds:0,wins:0,losses:0,resets:0, initBal:null,picking:false }; var panel=document.createElement('div'); panel.id='__mines_panel'; panel.innerHTML=` <style> #__mines_panel{ position:fixed;bottom:60px;right:8px;z-index:999999; width:320px;max-width:calc(100vw - 16px);max-height:70vh; background:#12141c;color:#e2e4ea;border:1px solid #2a2e3d; border-radius:12px;font-family:-apple-system,sans-serif; font-size:13px;box-shadow:0 8px 32px rgba(0,0,0,.5); display:flex;flex-direction:column;overflow:hidden; touch-action:none; } #__mines_panel *{box-sizing:border-box;margin:0;padding:0} #__mines_panel .mp-head{ display:flex;align-items:center;justify-content:space-between; padding:10px 14px;background:#1a1d2a;cursor:move; border-bottom:1px solid #2a2e3d;flex-shrink:0; } #__mines_panel .mp-head b{font-size:14px;color:#4ade80} #__mines_panel .mp-close{ width:28px;height:28px;border-radius:6px;border:none; background:#2a2e3d;color:#e2e4ea;font-size:16px;cursor:pointer; } #__mines_panel .mp-tabs{ display:flex;border-bottom:1px solid #2a2e3d;flex-shrink:0; } #__mines_panel .mp-tab{ flex:1;padding:8px 4px;text-align:center;font-size:12px; background:none;border:none;color:#8b8fa3;cursor:pointer; border-bottom:2px solid transparent; } #__mines_panel .mp-tab.active{color:#4ade80;border-bottom-color:#4ade80} #__mines_panel .mp-body{ overflow-y:auto;padding:12px 14px;flex:1;min-height:0; } #__mines_panel .mp-row{ display:flex;gap:8px;margin-bottom:8px;flex-wrap:wrap; } #__mines_panel .mp-stat{ flex:1;min-width:60px;background:#1a1d2a;border-radius:8px;padding:8px 10px; } #__mines_panel .mp-stat small{display:block;font-size:10px;color:#8b8fa3;text-transform:uppercase;letter-spacing:.03em} #__mines_panel .mp-stat span{font-size:16px;font-weight:700;font-variant-numeric:tabular-nums} #__mines_panel .mp-btn{ width:100%;padding:10px;border:none;border-radius:8px; font-size:14px;font-weight:600;cursor:pointer;margin-bottom:6px; } #__mines_panel .mp-btn-go{background:#4ade80;color:#0c0e14} #__mines_panel .mp-btn-stop{background:#f87171;color:#fff} #__mines_panel .mp-btn-pick{background:#3b82f6;color:#fff} #__mines_panel .mp-btn-sec{background:#2a2e3d;color:#e2e4ea} #__mines_panel .mp-field{margin-bottom:8px} #__mines_panel .mp-field label{display:block;font-size:11px;color:#8b8fa3;margin-bottom:3px;text-transform:uppercase} #__mines_panel .mp-field input,#__mines_panel .mp-field select{ width:100%;padding:8px;background:#1a1d2a;border:1px solid #2a2e3d; color:#e2e4ea;border-radius:6px;font-size:13px; } #__mines_panel .mp-log{ font-family:ui-monospace,monospace;font-size:11px;line-height:1.6; max-height:200px;overflow-y:auto;background:#0c0e14; border-radius:6px;padding:8px; } #__mines_panel .mp-log .w{color:#4ade80} #__mines_panel .mp-log .l{color:#f87171} #__mines_panel .mp-log .r{color:#fbbf24} #__mines_panel .mp-log .a{color:#60a5fa} #__mines_panel .mp-sel-status{ font-size:11px;padding:4px 8px;border-radius:4px;margin-bottom:4px; display:flex;justify-content:space-between;align-items:center; } #__mines_panel .mp-sel-ok{background:#16382a;color:#4ade80} #__mines_panel .mp-sel-miss{background:#3b1a1a;color:#f87171} #__mines_fab{ position:fixed;bottom:16px;right:16px;z-index:999999; width:52px;height:52px;border-radius:50%;border:2px solid #2a2e3d; background:#12141c;color:#4ade80;font-size:20px; display:none;align-items:center;justify-content:center; cursor:pointer;box-shadow:0 4px 16px rgba(0,0,0,.6); font-family:-apple-system,sans-serif;touch-action:none; transition:background .2s; } #__mines_fab:active{background:#1a1d2a} #__mines_fab .fab-dot{ position:absolute;top:6px;right:6px;width:10px;height:10px; border-radius:50%;border:2px solid #12141c; } #__mines_fab .fab-count{ position:absolute;bottom:-2px;right:-2px; font-size:9px;background:#1a1d2a;color:#8b8fa3; padding:1px 4px;border-radius:8px;border:1px solid #2a2e3d; white-space:nowrap; } </style> <div class="mp-head" id="__mp_head"> <b>踩地雷 Bot</b> <div style="display:flex;gap:6px"> <button class="mp-close" id="__mp_mini" style="font-size:13px" title="縮小成浮動按鈕">—</button> <button class="mp-close" id="__mp_close">&times;</button> </div> </div> <div class="mp-tabs"> <button class="mp-tab active" data-tab="ctrl">控制</button> <button class="mp-tab" data-tab="cfg">參數</button> <button class="mp-tab" data-tab="sel">選擇器</button> <button class="mp-tab" data-tab="log">紀錄</button> </div> <div class="mp-body"> <!-- 控制面板 --> <div id="__tab_ctrl"> <div class="mp-row"> <div class="mp-stat"><small>局數</small><span id="__s_rounds">0</span></div> <div class="mp-stat"><small>勝</small><span id="__s_wins" style="color:#4ade80">0</span></div> <div class="mp-stat"><small>負</small><span id="__s_losses" style="color:#f87171">0</span></div> <div class="mp-stat"><small>勝率</small><span id="__s_wr">—</span></div> </div> <div class="mp-row"> <div class="mp-stat"><small>當前注</small><span id="__s_bet">0</span></div> <div class="mp-stat"><small>連輸</small><span id="__s_streak">0</span></div> <div class="mp-stat"><small>重置</small><span id="__s_resets" style="color:#fbbf24">0</span></div> <div class="mp-stat"><small>餘額</small><span id="__s_bal">—</span></div> </div> <button class="mp-btn mp-btn-go" id="__btn_start">開始策略</button> <button class="mp-btn mp-btn-stop" id="__btn_stop" style="display:none">停止</button> <div id="__sel_warn" style="display:none;background:#3b2a1a;color:#fbbf24;padding:8px;border-radius:6px;font-size:12px;margin-top:6px"> 請先到「選擇器」頁籤設定頁面元素 </div> </div> <!-- 參數設定 --> <div id="__tab_cfg" style="display:none"> <div class="mp-field"><label>底注金額</label><input type="number" id="__c_base" step="0.00001"></div> <div class="mp-field"><label>地雷數量</label><input type="number" id="__c_mines" min="1" max="24"></div> <div class="mp-field"><label>每輪開格數</label><input type="number" id="__c_picks" min="1" max="24"></div> <div class="mp-field"><label>輸了翻幾倍</label><input type="number" id="__c_multi" step="0.1"></div> <div class="mp-field"><label>最大連輸把數</label><input type="number" id="__c_maxl" min="1" max="10"></div> <div class="mp-field"><label>最多跑幾局</label><input type="number" id="__c_maxr" min="10"></div> <div class="mp-field"><label>每局間隔 (ms)</label><input type="number" id="__c_delay" step="100"></div> <button class="mp-btn mp-btn-sec" id="__btn_savecfg">儲存參數</button> </div> <!-- 選擇器設定 --> <div id="__tab_sel" style="display:none"> <div style="font-size:12px;color:#8b8fa3;margin-bottom:10px"> 點「選取」按鈕後，點擊頁面上對應的元素 </div> <div id="__sel_list"></div> <button class="mp-btn mp-btn-sec" id="__btn_auto" style="margin-top:8px">自動偵測</button> </div> <!-- 紀錄 --> <div id="__tab_log" style="display:none"> <div class="mp-log" id="__logbox"></div> </div> </div> `; document.body.appendChild(panel); var fab=document.createElement('div'); fab.id='__mines_fab'; fab.innerHTML='<span style="pointer-events:none">&#x1f4a3;</span><div class="fab-dot" style="background:#8b8fa3"></div><div class="fab-count"></div>'; document.body.appendChild(fab); function updateFab(){ var dot=fab.querySelector('.fab-dot'); var cnt=fab.querySelector('.fab-count'); if(ST.running){ dot.style.background='#4ade80'; dot.style.animation='none'; dot.style.boxShadow='0 0 6px #4ade80'; var total=ST.wins+ST.losses; cnt.textContent='W'+ST.wins+'/L'+ST.losses; cnt.style.display=''; }else{ dot.style.background='#8b8fa3'; dot.style.boxShadow='none'; cnt.style.display='none'; } } fab.addEventListener('click',function(){ fab.style.display='none'; panel.style.display='flex'; }); var tabs=panel.querySelectorAll('.mp-tab'); var tabIds=['ctrl','cfg','sel','log']; tabs.forEach(function(t,i){ t.addEventListener('click',function(){ tabs.forEach(function(x){x.classList.remove('active')}); t.classList.add('active'); tabIds.forEach(function(id){ document.getElementById('__tab_'+id).style.display='none'; }); document.getElementById('__tab_'+t.dataset.tab).style.display=''; }); }); (function(){ var head=document.getElementById('__mp_head'); var startX,startY,origX,origY,dragging=false; function onStart(e){ dragging=true; var ev=e.touches?e.touches[0]:e; startX=ev.clientX;startY=ev.clientY; var r=panel.getBoundingClientRect(); origX=r.left;origY=r.top; e.preventDefault(); } function onMove(e){ if(!dragging)return; var ev=e.touches?e.touches[0]:e; var dx=ev.clientX-startX,dy=ev.clientY-startY; panel.style.left=(origX+dx)+'px'; panel.style.top=(origY+dy)+'px'; panel.style.right='auto';panel.style.bottom='auto'; } function onEnd(){dragging=false} head.addEventListener('mousedown',onStart); head.addEventListener('touchstart',onStart,{passive:false}); document.addEventListener('mousemove',onMove); document.addEventListener('touchmove',onMove,{passive:false}); document.addEventListener('mouseup',onEnd); document.addEventListener('touchend',onEnd); })(); (function(){ var startX,startY,origX,origY,dragging=false,moved=false; function onStart(e){ dragging=true;moved=false; var ev=e.touches?e.touches[0]:e; startX=ev.clientX;startY=ev.clientY; var r=fab.getBoundingClientRect(); origX=r.left;origY=r.top; e.preventDefault(); } function onMove(e){ if(!dragging)return; var ev=e.touches?e.touches[0]:e; var dx=ev.clientX-startX,dy=ev.clientY-startY; if(Math.abs(dx)>4||Math.abs(dy)>4)moved=true; fab.style.left=(origX+dx)+'px'; fab.style.top=(origY+dy)+'px'; fab.style.right='auto';fab.style.bottom='auto'; } function onEnd(e){ if(dragging&&moved){ e.preventDefault();e.stopPropagation(); fab.addEventListener('click',function block(ev){ev.stopPropagation();fab.removeEventListener('click',block,true)},true); } dragging=false; } fab.addEventListener('mousedown',onStart); fab.addEventListener('touchstart',onStart,{passive:false}); document.addEventListener('mousemove',onMove); document.addEventListener('touchmove',onMove,{passive:false}); document.addEventListener('mouseup',onEnd); document.addEventListener('touchend',onEnd); })(); document.getElementById('__mp_close').addEventListener('click',function(){ panel.style.display='none'; fab.style.display='none'; }); document.getElementById('__mp_mini').addEventListener('click',function(e){ e.stopPropagation(); panel.style.display='none'; fab.style.display='flex'; updateFab(); }); window.__MINES_BOT={toggle:function(){ if(panel.style.display==='none'&&fab.style.display==='none'){ panel.style.display='flex'; }else if(panel.style.display!=='none'){ panel.style.display='none'; fab.style.display='flex'; updateFab(); }else{ fab.style.display='none'; panel.style.display='flex'; } }}; function loadCfgUI(){ document.getElementById('__c_base').value=C.baseBet; document.getElementById('__c_mines').value=C.mines; document.getElementById('__c_picks').value=C.picks; document.getElementById('__c_multi').value=C.multiOnLoss; document.getElementById('__c_maxl').value=C.maxLossStreak; document.getElementById('__c_maxr').value=C.maxRounds; document.getElementById('__c_delay').value=C.delayRound; } loadCfgUI(); document.getElementById('__btn_savecfg').addEventListener('click',function(){ C.baseBet=parseFloat(document.getElementById('__c_base').value)||0.00001; C.mines=parseInt(document.getElementById('__c_mines').value)||4; C.picks=parseInt(document.getElementById('__c_picks').value)||2; C.multiOnLoss=parseFloat(document.getElementById('__c_multi').value)||3; C.maxLossStreak=parseInt(document.getElementById('__c_maxl').value)||3; C.maxRounds=parseInt(document.getElementById('__c_maxr').value)||500; C.delayRound=parseInt(document.getElementById('__c_delay').value)||2500; ST.bet=C.baseBet; addLog('參數已更新','a'); var btn=document.getElementById('__btn_savecfg'); btn.textContent='已儲存 ✓';btn.style.background='#4ade80';btn.style.color='#0c0e14'; setTimeout(function(){btn.textContent='儲存參數';btn.style.background='#2a2e3d';btn.style.color='#e2e4ea';},1500); }); var selKeys=[ {key:'betInput',label:'下注輸入框'}, {key:'betButton',label:'下注按鈕'}, {key:'cashoutButton',label:'Cashout 按鈕 (可自動找)'}, {key:'tiles',label:'格子 (25個)'}, {key:'balance',label:'餘額顯示 (選填)'} ]; function renderSelectors(){ var html=''; selKeys.forEach(function(item){ var ok=!!S[item.key]; html+='<div class="mp-sel-status '+(ok?'mp-sel-ok':'mp-sel-miss')+'">' +'<span>'+item.label+(ok?' ✓':' ✗')+'</span>' +'<button class="mp-btn-pick" style="padding:4px 10px;font-size:11px;border:none;border-radius:4px;cursor:pointer;background:#3b82f6;color:#fff" data-pick="'+item.key+'">選取</button>' +'</div>'; }); document.getElementById('__sel_list').innerHTML=html; document.querySelectorAll('[data-pick]').forEach(function(btn){ btn.addEventListener('click',function(){ startPick(btn.dataset.pick); }); }); } renderSelectors(); function startPick(key){ var label=selKeys.find(function(x){return x.key===key}).label; addLog('請點擊頁面上的「'+label+'」','a'); panel.style.display='none'; var banner=document.createElement('div'); banner.id='__mines_pick_banner'; banner.style.cssText='position:fixed;top:0;left:0;right:0;z-index:999998;background:#1a1d2a;color:#fbbf24;padding:14px 20px;font-size:14px;font-family:sans-serif;text-align:center;pointer-events:none;box-shadow:0 4px 12px rgba(0,0,0,.5)'; banner.textContent='請點擊「'+label+'」元素'; document.body.appendChild(banner); var cancelBtn=document.createElement('div'); cancelBtn.style.cssText='position:fixed;top:50px;right:12px;z-index:999998;background:#f87171;color:#fff;padding:8px 14px;border-radius:6px;font-size:13px;font-family:sans-serif;cursor:pointer'; cancelBtn.textContent='取消選取'; document.body.appendChild(cancelBtn); cancelBtn.addEventListener('click',function(e){ e.stopPropagation(); cleanup(); panel.style.display='flex'; addLog('已取消選取','r'); }); var handled=false; function cleanup(){ handled=true; banner.remove(); cancelBtn.remove(); document.removeEventListener('click',handler,true); } function handler(e){ if(handled)return; var el=e.target; if(el===cancelBtn||el===banner)return; if(el.closest&&(el.closest('#__mines_panel')||el.closest('#__mines_fab')))return; e.preventDefault(); e.stopPropagation(); var sel=genSel(el); S[key]=sel; addLog(label+' → '+sel,'a'); cleanup(); panel.style.display='flex'; renderSelectors(); checkReady(); } setTimeout(function(){ document.addEventListener('click',handler,true); },400); } document.getElementById('__btn_auto').addEventListener('click',function(){ addLog('開始自動偵測...','a'); var inputs=document.querySelectorAll('input'); for(var i=0;i<inputs.length;i++){ var inp=inputs[i]; if(inp.closest('#__mines_panel'))continue; var ph=(inp.placeholder||'').toLowerCase(); var nm=(inp.name||'').toLowerCase(); var ar=(inp.getAttribute('aria-label')||'').toLowerCase(); var parent=inp.parentElement; var parentText=''; for(var up=0;up<5&&parent;up++){ parentText+=parent.textContent||''; parent=parent.parentElement; } parentText=parentText.toLowerCase(); if( ph.includes('bet')||ph.includes('amount')||ph.includes('金額')|| nm.includes('bet')||nm.includes('amount')|| ar.includes('bet')||ar.includes('amount')||ar.includes('金額')|| (parentText.includes('金額')&&!parentText.includes('礦山')) ){ S.betInput=genSel(inp); addLog('下注輸入框 → '+S.betInput,'a'); break; } } if(!S.betInput){ for(var i=0;i<inputs.length;i++){ if(!inputs[i].closest('#__mines_panel')&&inputs[i].type!=='range'&&inputs[i].type!=='hidden'&&inputs[i].type!=='checkbox'&&inputs[i].type!=='radio'){ S.betInput=genSel(inputs[i]); addLog('下注輸入框 (猜測) → '+S.betInput,'a'); break; } } } var btns=document.querySelectorAll('button'); var betBtnCandidates=[]; var cashoutCandidates=[]; btns.forEach(function(btn){ if(btn.closest('#__mines_panel'))return; var txt=btn.textContent.trim(); var txtL=txt.toLowerCase(); if(txtL==='bet'||txt==='投注'||txt==='下注'||txtL==='start'||txtL==='play'){ betBtnCandidates.push(btn); } if(txtL.includes('cashout')||txtL.includes('cash out')|| txt.includes('提現')||txt.includes('取款')||txt.includes('兌現')|| txtL.includes('withdraw')||txtL.includes('take')){ cashoutCandidates.push(btn); } }); if(betBtnCandidates.length>0){ betBtnCandidates.sort(function(a,b){ return(b.offsetWidth*b.offsetHeight)-(a.offsetWidth*a.offsetHeight); }); S.betButton=genSel(betBtnCandidates[0]); addLog('下注按鈕 → '+S.betButton+' ('+betBtnCandidates[0].textContent.trim()+')','a'); } if(cashoutCandidates.length>0){ S.cashoutButton=genSel(cashoutCandidates[0]); addLog('Cashout → '+S.cashoutButton+' ('+cashoutCandidates[0].textContent.trim()+')','a'); } if(!S.cashoutButton){ addLog('Cashout 按鈕在下注後才會出現，先跳過','r'); } var classMap={}; document.querySelectorAll('*').forEach(function(el){ if(el.closest('#__mines_panel'))return; if(el.className&&typeof el.className==='string'){ el.className.trim().split(/\s+/).forEach(function(c){ if(c){classMap[c]=(classMap[c]||0)+1} }); } }); var found25=false; for(var cls in classMap){ if(classMap[cls]===25){ var testEls=document.querySelectorAll('.'+CSS.escape(cls)); var first=testEls[0]; if(first&&first.offsetWidth>10&&first.offsetWidth<200&&first.offsetHeight>10){ S.tiles='.'+cls; addLog('格子 → .'+cls+' (25個)','a'); found25=true; break; } } } if(!found25){ addLog('沒有找到 25 個格子，請手動選取其中一格','r'); } var allEls=document.querySelectorAll('*'); for(var i=0;i<allEls.length;i++){ var el=allEls[i]; if(el.closest('#__mines_panel'))continue; if(el.children.length>2)continue; var txt=el.textContent.trim(); if(/^\$[\d,.]+$/.test(txt)&&el.offsetWidth>0){ S.balance=genSel(el); addLog('餘額 → '+S.balance+' ('+txt+')','a'); break; } } renderSelectors(); checkReady(); addLog('偵測完成，缺少的請手動選取','r'); }); function genSel(el){ if(el.id)return'#'+el.id; if(el.getAttribute('data-testid'))return'[data-testid="'+el.getAttribute('data-testid')+'"]'; var tag=el.tagName.toLowerCase(); var cls=el.className&&typeof el.className==='string'?'.'+el.className.trim().split(/\s+/).slice(0,2).join('.'):''; return tag+cls; } function checkReady(){ var ready=S.betInput&&S.tiles; var hasBetBtn=!!findBtnByText(['投注','Bet','下注']); if(!hasBetBtn)ready=false; document.getElementById('__sel_warn').style.display=ready?'none':'block'; if(!ready&&!hasBetBtn){ document.getElementById('__sel_warn').textContent='找不到「投注」按鈕，請確認在踩地雷頁面'; }else if(!ready){ document.getElementById('__sel_warn').textContent='請先到「選擇器」頁籤設定頁面元素'; } document.getElementById('__btn_start').disabled=!ready; document.getElementById('__btn_start').style.opacity=ready?'1':'0.4'; return ready; } checkReady(); function updateUI(){ var total=ST.wins+ST.losses; document.getElementById('__s_rounds').textContent=total; document.getElementById('__s_wins').textContent=ST.wins; document.getElementById('__s_losses').textContent=ST.losses; document.getElementById('__s_wr').textContent=total?(ST.wins/total*100).toFixed(1)+'%':'—'; document.getElementById('__s_bet').textContent=ST.bet.toFixed(6); document.getElementById('__s_streak').textContent=ST.lossStreak; document.getElementById('__s_resets').textContent=ST.resets; var bal=getBalance(); document.getElementById('__s_bal').textContent=bal?bal.toFixed(6):'—'; updateFab(); } function addLog(msg,cls){ var box=document.getElementById('__logbox'); var d=document.createElement('div'); d.className=cls||''; var now=new Date(); var ts=String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0')+':'+String(now.getSeconds()).padStart(2,'0'); d.textContent=ts+' '+msg; box.appendChild(d); if(box.children.length>200)box.removeChild(box.firstChild); box.scrollTop=box.scrollHeight; } function getBalance(){ if(!S.balance)return null; var el=document.querySelector(S.balance); if(!el)return null; return parseFloat(el.textContent.replace(/[^0-9.]/g,''))||null; } async function setBet(amount){ var val=amount.toFixed(4); function getInp(){ return document.querySelector(S.betInput); } var inp=getInp(); if(!inp)throw new Error('找不到下注輸入框'); for(var w=0;w<15;w++){ inp=getInp(); if(inp&&!inp.disabled&&!inp.readOnly&&inp.offsetParent!==null)break; await wait(200); } inp=getInp(); if(!inp)throw new Error('等待後仍找不到下注輸入框'); function checkVal(){ var actual=parseFloat(getInp().value)||0; return Math.abs(actual-amount)<0.5; } function reactSet(){ var i=getInp(); var setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set; var tracker=i._valueTracker; if(tracker)tracker.setValue(''); setter.call(i,val); i.dispatchEvent(new Event('input',{bubbles:true})); i.dispatchEvent(new Event('change',{bubbles:true})); } function reactSetWithClear(){ var i=getInp(); var setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set; var tracker=i._valueTracker; if(tracker)tracker.setValue(i.value||'x'); setter.call(i,''); i.dispatchEvent(new InputEvent('input',{bubbles:true,data:null,inputType:'deleteContentBackward'})); i.dispatchEvent(new Event('change',{bubbles:true})); if(tracker)tracker.setValue(''); setter.call(i,val); i.dispatchEvent(new InputEvent('input',{bubbles:true,data:val,inputType:'insertText'})); i.dispatchEvent(new Event('change',{bubbles:true})); } async function execCmdSet(){ var i=getInp(); i.focus(); i.select(); await wait(30); document.execCommand('selectAll',false,null); document.execCommand('delete',false,null); await wait(30); document.execCommand('insertText',false,val); } async function keyboardSet(){ var i=getInp(); i.focus(); i.select(); i.dispatchEvent(new KeyboardEvent('keydown',{key:'a',code:'KeyA',ctrlKey:true,bubbles:true})); i.dispatchEvent(new KeyboardEvent('keydown',{key:'Backspace',code:'Backspace',keyCode:8,bubbles:true})); var setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set; setter.call(i,''); i.dispatchEvent(new InputEvent('input',{bubbles:true,data:null,inputType:'deleteContentBackward'})); await wait(30); for(var ci=0;ci<val.length;ci++){ var ch=val[ci]; i.dispatchEvent(new KeyboardEvent('keydown',{key:ch,bubbles:true})); i.dispatchEvent(new KeyboardEvent('keypress',{key:ch,bubbles:true})); var prev=i.value; setter.call(i,prev+ch); i.dispatchEvent(new InputEvent('input',{bubbles:true,data:ch,inputType:'insertText'})); i.dispatchEvent(new KeyboardEvent('keyup',{key:ch,bubbles:true})); } i.dispatchEvent(new Event('change',{bubbles:true})); } async function presetThenSet(){ var presetBtn=findBtnByText(['10','100','1']); if(presetBtn){ presetBtn.click(); await wait(300); } reactSetWithClear(); } var strategies=[ {name:'reactClear',fn:async function(){tapElement(getInp());getInp().focus();await wait(150);reactSetWithClear()}}, {name:'execCmd',fn:async function(){await execCmdSet()}}, {name:'react',fn:async function(){getInp().focus();await wait(100);reactSet()}}, {name:'keyboard',fn:async function(){await keyboardSet()}}, {name:'preset+react',fn:async function(){await presetThenSet()}} ]; for(var si=0;si<strategies.length;si++){ var s=strategies[si]; try{ await s.fn(); await wait(150); if(checkVal()){ addLog(' 輸入框: '+getInp().value+' ('+s.name+')','a'); return; } }catch(e){} addLog(' '+s.name+' 失敗, 實際:'+getInp().value,'r'); await wait(100); } for(var fi=0;fi<2;fi++){ await wait(500); tapElement(getInp()); getInp().focus(); await wait(300); reactSetWithClear(); await wait(200); if(checkVal()){ addLog(' 輸入框: '+getInp().value+' (finalRetry)','a'); return; } } addLog(' 輸入框最終: '+getInp().value+' (目標:'+val+') 全策略失敗','l'); } function findBtnByText(keywords){ var selectors='button,a,[role="button"]'; var els=document.querySelectorAll(selectors); for(var i=0;i<els.length;i++){ var b=els[i]; if(b.closest('#__mines_panel')||b.closest('#__mines_fab'))continue; var txt=b.textContent.trim(); for(var k=0;k<keywords.length;k++){ if(txt===keywords[k]||txt.toLowerCase()===keywords[k].toLowerCase()){ return b; } } } for(var i=0;i<els.length;i++){ var b=els[i]; if(b.closest('#__mines_panel')||b.closest('#__mines_fab'))continue; var txt=b.textContent.trim().toLowerCase(); for(var k=0;k<keywords.length;k++){ if(txt.includes(keywords[k].toLowerCase())){ return b; } } } return null; } function findRandomBtn(){ var keywords=['隨機選取一個方塊','隨機選取','隨機','Random','Pick random','Random tile','Pick a random','random']; var btn=findBtnByText(keywords); if(btn)return btn; var all=document.querySelectorAll('button,a,div,span'); for(var i=0;i<all.length;i++){ var el=all[i]; if(el.closest('#__mines_panel')||el.closest('#__mines_fab'))continue; if(!el.offsetParent)continue; var txt=(el.textContent||'').trim().toLowerCase(); var title=(el.getAttribute('title')||'').toLowerCase(); var aria=(el.getAttribute('aria-label')||'').toLowerCase(); for(var k=0;k<keywords.length;k++){ var kw=keywords[k].toLowerCase(); if(txt.includes(kw)||title.includes(kw)||aria.includes(kw)){ return el; } } } return null; } function clickBetButton(){ var btn=findBtnByText(['投注','Bet','下注','Start','Play']); if(!btn)throw new Error('找不到投注按鈕（頁面上沒有「投注」按鈕，可能不在踩地雷頁面）'); if(btn.offsetWidth<100){ addLog('警告：找到的按鈕太小('+btn.offsetWidth+'px)，可能不對','r'); } tapElement(btn); } function findCashoutButton(){ return findBtnByText(['提現','Cashout','Cash Out','取款','兌現','Pick up']); } function clickEl(sel,name){ var el=document.querySelector(sel); if(!el)throw new Error('找不到'+name); el.click(); } function getOpenTiles(){ var all=document.querySelectorAll(S.tiles); addLog(' 找到 '+all.length+' 個格子元素','a'); if(all.length===0)return[]; var open=Array.from(all).filter(function(t){ var cls=(t.className||'').toLowerCase(); if(t.disabled||t.getAttribute('aria-disabled')==='true')return false; if(/revealed|opened|bomb|mine|gem|diamond/i.test(cls))return false; var hasImage=t.querySelector('img,svg'); if(hasImage)return false; return true; }); addLog(' 可點格子: '+open.length+' 個','a'); if(open.length===0&&all.length===25){ addLog(' 過濾後為 0，改用全部格子','r'); return Array.from(all); } return open; } function tapElement(el){ var rect=el.getBoundingClientRect(); var x=rect.left+rect.width/2; var y=rect.top+rect.height/2; try{ var touchObj=new Touch({ identifier:Date.now(), target:el, clientX:x,clientY:y, pageX:x+window.scrollX, pageY:y+window.scrollY }); el.dispatchEvent(new TouchEvent('touchstart',{ bubbles:true,cancelable:true,touches:[touchObj],targetTouches:[touchObj],changedTouches:[touchObj] })); el.dispatchEvent(new TouchEvent('touchend',{ bubbles:true,cancelable:true,touches:[],targetTouches:[],changedTouches:[touchObj] })); }catch(e){} el.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,clientX:x,clientY:y})); el.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,clientX:x,clientY:y})); el.click(); } function checkStillOnPage(){ var url=window.location.href.toLowerCase(); return url.includes('mine'); } function wait(ms){return new Promise(function(r){setTimeout(r,ms)})} async function run(){ if(ST.running)return; if(!checkReady()){addLog('選擇器未設定完成','l');return} ST.running=true;ST.stop=false; ST.bet=C.baseBet;ST.lossStreak=0; ST.rounds=0;ST.wins=0;ST.losses=0;ST.resets=0; ST.initBal=getBalance(); document.getElementById('__btn_start').style.display='none'; document.getElementById('__btn_stop').style.display=''; addLog('=== 策略啟動 ===','a'); addLog('底注:'+C.baseBet+' 地雷:'+C.mines+' 開格:'+C.picks,'a'); while(ST.running&&!ST.stop&&ST.rounds<C.maxRounds){ ST.rounds++; try{ if(!checkStillOnPage()){ addLog('已離開踩地雷頁面，自動停止','l'); break; } addLog('['+ST.rounds+'] 下注 '+ST.bet.toFixed(6),'a'); await setBet(ST.bet); await wait(300); clickBetButton(); addLog(' 已點投注','a'); await wait(C.delayAfterBet); if(!checkStillOnPage()){ addLog('點擊後被導航離開，自動停止','l'); break; } var busted=false; for(var p=0;p<C.picks;p++){ var clicked=false; for(var rt=0;rt<10;rt++){ var randBtn=findRandomBtn(); if(randBtn){ tapElement(randBtn); addLog(' 開第'+(p+1)+'格 (隨機按鈕)','a'); clicked=true; break; } await wait(400); } if(!clicked){ var tiles=getOpenTiles(); if(tiles.length>0){ var idx=Math.floor(Math.random()*tiles.length); tapElement(tiles[idx]); addLog(' 開第'+(p+1)+'格 (直接點格子)','a'); clicked=true; }else{ addLog(' 第'+(p+1)+'格找不到可點元素','r'); } } await wait(C.delayClick); await wait(200); var afterPickCashout=findCashoutButton(); if(!afterPickCashout&&p<C.picks-1){ busted=true; addLog(' 開格後踩雷，停止開格','l'); break; } } await wait(500); if(!busted){ var coBtn=findCashoutButton(); if(coBtn&&!coBtn.disabled){ tapElement(coBtn); ST.wins++; addLog('['+ST.rounds+'] 贏了！Cashout','w'); ST.bet=C.baseBet; ST.lossStreak=0; await wait(800); }else{ busted=true; } } if(busted){ ST.losses++; ST.lossStreak++; addLog('['+ST.rounds+'] 踩雷 連輸'+ST.lossStreak,'l'); if(ST.lossStreak>=C.maxLossStreak){ ST.resets++; ST.bet=C.baseBet; ST.lossStreak=0; addLog(' 連輸'+C.maxLossStreak+'把 重置底注','r'); }else{ ST.bet*=C.multiOnLoss; addLog(' 下局加注 '+ST.bet.toFixed(6),'r'); } } updateUI(); await wait(C.delayRound); }catch(err){ addLog('錯誤: '+err.message,'l'); await wait(5000); } } ST.running=false; document.getElementById('__btn_start').style.display=''; document.getElementById('__btn_stop').style.display='none'; var total=ST.wins+ST.losses; addLog('=== 結算 ===','a'); addLog('共'+total+'局 勝'+ST.wins+' 負'+ST.losses+' 勝率'+(total?(ST.wins/total*100).toFixed(1):0)+'%','a'); addLog('重置'+ST.resets+'次','a'); updateFab(); } document.getElementById('__btn_start').addEventListener('click',function(){run()}); document.getElementById('__btn_stop').addEventListener('click',function(){ ST.stop=true;ST.running=false; document.getElementById('__btn_start').style.display=''; document.getElementById('__btn_stop').style.display='none'; addLog('已手動停止','r'); updateUI(); }); addLog('Bot 已載入，請先設定選擇器','a'); }());